  if(req.method==='POST'&&u.pathname==='/api/setup'){if(isProduction())return sendJson(res,403,{error:'SETUP_DISABLED_IN_PRODUCTION'});const b=await bodyJson(req),next=loadConfig();if(b.clientId!==undefined){const x=esc(b.clientId);if(x&&!/^[a-z0-9]{10,80}$/i.test(x))return sendJson(res,400,{error:'CLIENT_ID_INVALID'});next.clientId=x;}if(['device','implicit'].includes(b.authMode))next.authMode=b.authMode;if(b.loginScopes!==undefined)next.viewerScopes=esc(b.loginScopes).slice(0,500)||VIEWER_SCOPES;if(b.adminScopes!==undefined)next.adminScopes=esc(b.adminScopes).slice(0,500)||ADMIN_SCOPES;next.adminTwitchLogin='sovara_';saveConfig(next);return sendJson(res,200,{ok:true,configured:!!next.clientId,redirectUri:`${requestBaseUrl(req,next)}/auth/callback`});}
  if(req.method==='POST'&&u.pathname==='/api/auth/device/start'){if(!config.clientId)return sendJson(res,400,{error:'TWITCH_NOT_CONFIGURED'});const r=await postForm('https://id.twitch.tv/oauth2/device',{client_id:config.clientId,scopes:config.viewerScopes||VIEWER_SCOPES});if(!r.ok)return sendJson(res,r.status,{error:'TWITCH_DEVICE_START_FAILED',details:r.data});const attemptId=id();deviceAttempts.set(attemptId,{deviceCode:r.data.device_code,expiresAt:now()+Number(r.data.expires_in||1800)*1000,interval:Number(r.data.interval||5),lastPoll:0});return sendJson(res,200,{attemptId,userCode:r.data.user_code,verificationUri:r.data.verification_uri,expiresIn:r.data.expires_in,interval:r.data.interval});}
  if(req.method==='POST'&&u.pathname==='/api/auth/device/poll'){if(!config.clientId)return sendJson(res,400,{error:'TWITCH_NOT_CONFIGURED'});const b=await bodyJson(req),a=deviceAttempts.get(String(b.attemptId||''));if(!a||a.expiresAt<now())return sendJson(res,410,{error:'DEVICE_CODE_EXPIRED'});if(now()-a.lastPoll<Math.max(1000,a.interval*1000-500))return sendJson(res,202,{pending:true});a.lastPoll=now();const r=await postForm('https://id.twitch.tv/oauth2/token',{client_id:config.clientId,scopes:config.viewerScopes||VIEWER_SCOPES,device_code:a.deviceCode,grant_type:'urn:ietf:params:oauth:grant-type:device_code'});if(!r.ok){const code=r.data&&String(r.data.message||r.data.error||'').toLowerCase();if(r.status===400&&(code.includes('pending')||code.includes('authorization')))return sendJson(res,202,{pending:true});if(code.includes('slow')){a.interval+=2;return sendJson(res,202,{pending:true,slowDown:true});}return sendJson(res,r.status,{error:'TWITCH_DEVICE_POLL_FAILED',details:r.data});}try{const twitch=await validateTwitchToken(r.data.access_token,config.clientId);deviceAttempts.delete(String(b.attemptId));maybeBindAdmin(twitch);createSession(res,twitch,r.data.access_token);const st=loadState();bindManagedAdmin(st,twitch);getUser(st,twitch);recalcGiveaway(st);saveState(st);if(isOwner(twitch,loadConfig()))setAdminRuntime(twitch,r.data.access_token);return sendJson(res,200,{ok:true,twitch,isAdmin:isAdmin(twitch,loadConfig(),st),isOwner:isOwner(twitch,loadConfig())});}catch(e){return sendJson(res,400,{error:'TWITCH_VALIDATE_FAILED',message:e.message});}}
  if(req.method==='POST'&&u.pathname==='/api/auth/implicit/start'){if(!config.clientId)return sendJson(res,400,{error:'TWITCH_NOT_CONFIGURED'});const state=id(18);oauthStates.set(state,{expiresAt:now()+10*60*1000,type:'viewer'});const redirect=`${requestBaseUrl(req,config)}/auth/callback`,q=new URLSearchParams({response_type:'token id_token',client_id:config.clientId,redirect_uri:redirect,scope:config.viewerScopes||VIEWER_SCOPES,state});return sendJson(res,200,{state,url:`https://id.twitch.tv/oauth2/authorize?${q.toString()}`,redirectUri:redirect});}
